\begin{claim}
\label{claim:equivalence} 
A distribution $\mu$ is an equilibria for a marketplace with 2 populations of users of size $N/2$ located at vectors $u_1$ and $u_2$ and with producer cost function $c(\p) = \|p\|_2^{\beta}$ if and only if $\mu$ is an equilibria for a marketplace with 2 users located at vectors $\frac{u_1}{\|u_1\|}$ and $\frac{u_2}{\|u_2\|}$ and with producer cost function $c(\p) = \frac{2}{N} \|p\|_2^{\beta}$. 
\end{claim}

\begin{restatable}{lemma}{necessarysuff}
\label{claim:necessarysuff}
Let $\UMatrix = [u_1; u_2; \ldots; u_N]$ be the $N \times D$ matrix of users vectors. Given a set $S \subseteq \mathbb{R}_{\ge 0}^N$ and distributions $H_1, \ldots, H_N$ over $\mathbb{R}_{\ge 0}$, suppose that the following conditions hold:   
\begin{description}
    \item{(C1)} Every $z^* \in S$ is a maximizer of the equation:
    \begin{equation}
\label{eq:reparam}
 \max_{z \in \mathbb{R}_{\ge 0}^D} \sum_{i=1}^N H_i(z_i) - c_{\UMatrix}(z),
\end{equation}
where $c_{\UMatrix}(z) := \min \left\{c(\p) \mid \p \in \mathbb{R}_{\ge 0}^D, \UMatrix p=z  \right\}$.
    \item{(C2)} There exists a random variable $Z$ with support $S$, such that the marginal distribution $Z_i$ has cdf equal to $H_i(z)^{1/(P-1)}$.
    \item{(C3)} $Z$ is distributed as $\UMatrix Y$ with $Y \sim \mu$, for some distribution $\mu$ over $\mathbb{R}_{\ge 0}^D$.  
\end{description} 
Then, the distribution $\mu$ from (C3) is a symmetric mixed Nash equilibrium. Moreover, every symmetric mixed Nash equilibrium $\mu$ is associated with some $(H_1, \ldots, H_N, S)$ that satisfy (C1)-(C3). 
\end{restatable}

\begin{restatable}{corollary}{betageneral}
\label{cor:beta}
Let $\|\cdot\|_{*}$ denote the dual norm of $\|\cdot\|$, defined to be $\|\p\|_{*} = \max_{\|\p\| = 1, \p \in \bR_{\ge 0}^D} \langle q, \p \rangle$. Let $Z:= \|\sum_{n=1}^{N} \frac{u_n}{\|u_n\|_{*}} \|_{*}$. Then, 
\begin{equation}
\label{eq:betacondition}
\beta^* \le \frac{\log (N)}{\log(N) - \log(Z)}.
\end{equation}
\end{restatable}

\begin{restatable}{corollary}{betaone}
\label{cor:beta1}
The threshold $\beta^*$ is always at least $1$. That is, if $\beta = 1$, there exists a single-genre equilibrium. 
\end{restatable}

\begin{restatable}{corollary}{betap}
\label{cor:betap}
Let the cost function be $c(\p) = \|\p\|_{q}^{\beta}$. For any set of user vectors, it holds that $\beta^* \ge q$. If the user vectors are equal to the standard basis vectors $\left\{e_1, \ldots, e_D \right\}$, then $\beta^*$ is equal to $q$. 
\end{restatable}

\begin{corollary}
\label{cor:onepopulation}
Suppose that there is a single population of $N$ users, all of whose embeddings are at the same vector $u$. Then, there is a symmetric mixed Nash equilibrium $\mu$ supported on $\left\{ q p^* \mid q \in [0, N^{\frac{1}{\beta}}] \right\}$ where $p^* \in \argmax_{\|p \| = 1 } \langle p, u \rangle$. The cumulative distribution function of $q = \|p\| \sim \mu$ is $F(q) = \left(q/N\right)^{\beta / (P-1)}$. 
\end{corollary}

\begin{restatable}{corollary}{singlegenrestructure}
\label{cor:singlegenrestructure}
If there exists $\mu$ with $|\Genre(\mu)| = 1$, then the corresponding producer direction maximizes Nash social welfare of the users:
\begin{equation}
\label{eq:direction}
 \Genre(\mu) = \argmax_{\|\p\|=1 \mid \p \in \bR_{\ge 0}^D} \sum_{i=1}^N \log(\langle \p, u_i\rangle).    
\end{equation}
\end{restatable}

\begin{restatable}{corollary}{twousers}
\label{cor:2users}
Suppose that there are $N$ users split equally between two linearly independently vectors $u_1, u_2 \in \mathbb{R}_{\ge 0}^D$, and let $\theta^* := \cos^{-1}\left( \frac{\langle u_1, u_2\rangle}{\|u_1\|_2 \|u_2\|} \right)$. Let the cost function be $c(\p) = \|\p\|_{2}^{\beta}$. Then it holds that: 
\[\beta^*  = \frac{2}{1 - \cos(\theta^*)}. \]
\end{restatable}

\begin{corollary}
\label{cor:2usersprofit}
Suppose that there are 2 users located at the standard basis vectors $e_1, e_2 \in \mathbb{R}^2$, and the cost function is $c(\p) = \|p\|_2^{\beta}$. For $P = 2$ and $\beta \ge \beta^* = 2$, there is an equilibrium $\mu$ where $\ProfitEq(\mu) = 1 - \frac{2}{\beta}$.
\end{corollary}

\begin{definition}[Finite-genre equilibria for $P = \infty$]
\label{def:infinitegenre}
Let $u_1, \ldots, u_N \in \mathbb{R}_{\ge 0}^D$ be a set of users and let $c(\p) = \|p\|_2^{\beta}$ be the cost function. A set of \textit{genres} $d_1, \ldots, d_G \in \mathbb{R}_{\ge 0}^D$ such that $\|d_i\|_2 = 1$ for all $1 \le g \le G$, a set of \textit{conditional quality distributions} $F_1, F_2, \ldots, F_G$ over $\mathbb{R}_{\ge 0}$, and a set of weights $\alpha_1, \ldots, \alpha_G \ge 0$ such that $\sum_{g=1}^G \alpha_g = 1$ forms a finite-genre equilibrium if the following condition holds for 
\begin{equation}
\label{eq:infinitecondition}
\p^* \in \argmax_{\p \in \mathbb{R}_{\ge 0}^D} \left(\sum_{i=1}^N \left(\prod_{g=1}^G \left(\FMax_g \left(\frac{\langle u_i, \p \rangle}{\langle u_i, d_g \rangle} \right)\right)^{\alpha_i} \right) - c(\p) \right)    
\end{equation}
for any $\p^* = q_i d_i$ such that $1 \le i \le G$ and $q_i \in \text{supp}(F_i)$.

More formally, we can quantify the producer profit at equilibrium as follows. At a symmetric equilibria $\mu$, all producers receive the same expected profit given by: 
\begin{equation}
   \ProfitEq(\mu) := \mathbb{E}_{\p_1, \ldots, \p_P \sim \mu} [\Profit(\p_1; \p_{-1})] =  \mathbb{E} \Big[ \Big(\sum_{i=1}^N \Indicator[j^*(\u_i;\;\p_{1:P}) = 1]\Big) - \|\p_1\|^{\beta}  \Big],
\end{equation}

\begin{example}[1-dimensional setup]
\label{example:1d} 
Let $D = 1$, and suppose that there is a single user $\u_1 =1$. Suppose the cost function is $c(\p) = |\p|^{\beta}$. The unique symmetric mixed equilibrium $\mu$ is supported on the full interval $[0, 1]$ and has cumulative distribution function $F(\p) = \left(\p /N\right)^{\beta / (P-1)}$. We defer the derivation to Appendix \ref{sec:derivationexample1d}.
\end{example}

Since our characterization result (Theorem \ref{thm:infinitegenre}) focuses on finite-genre equilibria,  we restrict our formal definition of the infinite-producer limit to case of finite genres for technical convenience.

We arrive at a formalism by taking a limit of the conditions  in Lemma \ref{claim:necessarysuff} as $P \rightarrow \infty$. Let $\mu$ be a finite-genre distribution over $\mathbb{R}_{\ge 0}^D$. We can specify $\mu$ by the three attributes: the genres $d_1, \ldots, d_G$, the distributions $F_g$ over $\mathbb{R}_{\ge 0}$ corresponding to the distribution of $\|p\|$ for $p$ drawn from $\mu$ conditioned on $\p$ pointing in the direction of $d_g$, and the weights $\alpha_g$ corresponding to the probability that $\p \sim \mu$ points in the direction of $d_g$. In particular, $\mu$ can be described as follows: with probability $\alpha_g$, choose the vector $q_g d_g$ where $q_g$ is drawn from a distribution with cdf $F_g$. We see that the corresponding function $H_i$ from Lemma \ref{claim:necessarysuff} will be equal to:
\[H_i(z_i) = \left(\sum_{g=1}^G \alpha_g F_g\left(\frac{\langle u_i, \p \rangle}{\langle u_i, d_g \rangle} \right) \right)^{P-1}. \]
Note that the conditions (C2) and (C3) are essentially satisfied by construction; condition (C1) requires that 
\[\max_{\p \in \mathbb{R}_{\ge 0}^D} \left(\sum_{i=1}^N H_i(\langle u_i, \p\rangle) - c(\p) \right)\] is maximized for any $\p \in \text{supp}(\mu)$. This can be rewritten as requiring that any $\p^* \in \text{supp}(\mu)$ satisfies:
\[
  \p^* \in \argmax_{\p \in \mathbb{R}_{\ge 0}^D} \left(\sum_{i=1}^N \left(\sum_{g=1}^G \alpha_g F_g\left(\frac{\langle u_i, \p \rangle}{\langle u_i, d_g \rangle} \right) \right)^{P-1} - c(\p) \right).\]
Let's rewrite this in terms of winning producers: more formally, let $\FMax_g(\cdot) = (F_g(\cdot))^{P-1}$ denote the cumulative distribution function of the \textit{maximum} quality in a genre, conditioned on all producers choosing that genre. We call the distributions $\FMax_1, \ldots, \FMax_G$ the \textit{conditional quality distributions}. Then we obtain the following:
\begin{equation}
\label{eq:finitegenrep}
  \p^* \in \argmax_{\p \in \mathbb{R}_{\ge 0}^D} \left(\sum_{i=1}^N \left(\sum_{g=1}^G \alpha_g \left(\FMax_g\left(\frac{\langle u_i, \p \rangle}{\langle u_i, d_g \rangle} \right)\right)^{1/(P-1)} \right)^{P-1} - c(\p) \right).
\end{equation}
Taking a limit as $P \rightarrow \infty$, we see that 
\[\left(\sum_{g=1}^G \alpha_g F_g\left(\frac{\langle u_i, \p \rangle}{\langle u_i, d_g \rangle} \right)^{1/(P-1)}\right)^{P-1} \rightarrow \prod_{g=1}^G \left(F_g\left(\frac{\langle u_i, \p \rangle}{\langle u_i, d_g \rangle} \right)\right)^{\alpha_i}.\]
Thus, equation \ref{eq:finitegenrep} (informally speaking) approaches the following condition in the limit:  
\begin{equation}
\label{eq:infinitegenrecondition}
   \p^* \in \argmax_{\p \in \mathbb{R}_{\ge 0}^D} \left(\sum_{i=1}^N \left(\sum_{g=1}^G \alpha_g F_g\left(\frac{\langle u_i, \p \rangle}{\langle u_i, d_g \rangle} \right)^{1/(P-1)} \right)^{P-1} - c(\p) \right).
\end{equation}

\begin{restatable}{lemma}{cdf}
\label{lemma:cdf}
Suppose that $\mu$ is a symmetric equilibrium such that $\Genre(\mu)$ contains a single vector. Let $F$ be the cdf of the distribution over $\|\p\|$ where $\p \sim \mu$. Then, it holds that:
\begin{equation}
F(r) = \min\left(1, \left(\frac{r^{\beta}}{N}\right)^{1/(P-1)}\right). 
\end{equation}
\end{restatable}

\begin{lemma}
\label{lemma:conditiongen}
There exists a symmetric equilibrium $\mu$ with $|\Genre(\mu)| = 1$ if and only if: 
\begin{equation}
\label{eq:conditioninter}    
\inf_{p^* \in \Ballm} \sup_{y' \in \Set^{\beta}} \sum_{i=1}^N  \frac{y'_i}{(\langle \p^*, u_i \rangle)^{\beta}} \le N.
\end{equation}
\end{lemma}

\begin{lemma}
\label{lemma:FOC} 
Let there be 2 users located at $u_1, u_2 \in \mathbb{R}_{\ge 0}^D$ such that  $\|u_1\| = \|u_2\| = 1$, and let $\theta^* := \cos^{-1}\left( \langle u_1, u_2\rangle \right) > 0$ be the angle between the user vectors. Let the cost function be $c(\p) = \alpha \|p\|_2^{\beta}$ for $\alpha > 0$. For any $z \in \left\{\UMatrix p \mid p \in \mathbb{R}_{\ge 0}^D \right\}$, the first-order condition of equation \eqref{eq:reparam} can be written as: 
\[\begin{bmatrix}
h_1(z_1) \\
h_2(z_2)
\end{bmatrix} 
= \nabla_{z}(c_{\UMatrix}(z)).\]
More specifically, it holds that: 
\[\begin{bmatrix}
h_1(z_1) \\
h_2(z_2)
\end{bmatrix} = \beta \alpha \sin^{-\beta}(\theta^*) \left(z_1^2 + z_2^2 - 2 z_1 z_2 \cos(\theta^*) \right)^{\frac{\beta}{2} - 1} \begin{bmatrix}
z_1 - z_2 \cos(\theta^*) \\
z_2 - z_1 \cos(\theta^*)
\end{bmatrix},
\]
and if we represent $z = \UMatrix [r\cos(\theta), r \sin(\theta)]$, then it also holds that:
\[\begin{bmatrix}
h_1(z_1) \\
h_2(z_2)
\end{bmatrix}  = \beta \alpha r^{\beta - 1} \begin{bmatrix}
\frac{\sin(\theta^* - \theta)}{\sin(\theta^*)} \\
\frac{\sin(\theta)}{\sin(\theta^*)} 
\end{bmatrix}.   \]
\end{lemma}

\begin{lemma}
\label{lemma:inducedcost}
Let there be 2 users located at $u_1, u_2 \in \mathbb{R}_{\ge 0}^D$ such that  $\|u_1\| = \|u_2\| = 1$, and let $\theta^* := \cos^{-1}\left( \langle u_1, u_2\rangle \right) > 0$ be the angle between the user vectors. Let the cost function be $c(\p) = \alpha \|p\|_2^{\beta}$ for $\alpha > 0$. For any $z \in \left\{\UMatrix p \mid p \in \mathbb{R}_{\ge 0}^D \right\}$, the induced cost function is given by:
\[c_{\UMatrix}(z) = \alpha \sin^{-\beta}(\theta^*) \left(z_1^2 + z_2^2 - 2 z_1 z_2 \cos(\theta^*) \right)^{\frac{\beta}{2}}.\]
\end{lemma}

\begin{lemma}
\label{lemma:nonzero} 
Suppose that $\mu$ is a symmetric equilibrium such that $\Genre(\mu)$ contains a single vector $\p^*$. Then $p^* \in \text{span}(u_1, \ldots, u_N)$ (which also means that $\langle \p^*, u_i \rangle > 0$ for all $i$.) 
\end{lemma}
\begin{proof}
Assume for sake of contradiction that $\langle p^*, u_i \rangle = 0$ for some $i$. Suppose that $p' \in \text{supp}(\mu)$, and consider the vector $\p' + \epsilon \frac{u_i}{||u_i||}$. We see that $\p' + \epsilon \frac{u_i}{||u_i||}$ wins user $u_i$ with probability 1 whereas $\p'$ wins user $u_i$ with probability $1/P$. The probability that $\p + \epsilon u_i$ wins any other user is also at least the probability that $\p'$ wins $u_i$. By leveraging this discontinuity, we see there exists $\epsilon$ such that $\Profit(\p' + \epsilon \frac{u_i}{||u_i||}; [\mu, \ldots, \mu]) > \Profit(\p'; [\mu, \ldots, \mu]) + (1 - \frac{1}{P})$ which is a contradiction.

\begin{restatable}[Informal]{lemma}{optimization}
\label{lemma:optimizationprogram}
There exists a symmetric equilibrium $\mu$ with $|\Genre(\mu)| = 1$ if and only if: 
\begin{equation}
    \label{eq:optimizationprogrammain}
    \inf_{y \in \Set^{\beta}} \left(\sup_{y' \in \Set^{\beta}}   \sum_{i=1}^N  \frac{y'_i}{y_i} \right) = \sup_{y' \in \Set^{\beta}} \left(\inf_{y \in \Set^{\beta}} \sum_{i=1}^N  \frac{y'_i}{y_i}\right).
\end{equation}
\end{restatable}

\begin{lemma}[Formalization of Lemma \ref{lemma:optimizationprogram}]
\label{lemma:optimizationprogramrestated}
There exists a symmetric equilibrium $\mu$ with $|\Genre(\mu)| = 1$ if and only if: 
\begin{equation}
    \label{eq:optimizationprogramrestated}
\inf_{p^* \in \Ballm} \sup_{y' \in \Set^{\beta}} \sum_{i=1}^N  \frac{y'_i}{(\langle \p^*, u_i \rangle)^{\beta}} = \sup_{y' \in \Set^{\beta}}\inf_{p^* \in \Ballm}  \sum_{i=1}^N  \frac{y'_i}{(\langle \p^*, u_i \rangle)^{\beta}}.
\end{equation}
\end{lemma}

\begin{lemma}
\label{lemma:optsingledirection}
There is a symmetric equilibrium $\mu$ with $\Genre(\mu) = \left\{p^*\right\}$ if and only if:
\begin{equation}
\label{eq:optsingle}
  \sup_{y' \in \Set^{\beta}} \sum_{i=1}^N  \frac{y'_i}{(\langle \p^*, u_i \rangle)^{\beta}} \le N. 
\end{equation}
\end{lemma}

\begin{lemma}
\label{lemma:regionscolor}
Let there be 2 users located at $u_1, u_2 \in \mathbb{R}_{\ge 0}^D$ such that  $\|u_1\| = \|u_2\| = 1$, and let $\theta^* := \cos^{-1}\left( \langle u_1, u_2\rangle \right) > 0$ be the angle between the user vectors. Let the cost function be $c(\p) = \alpha \|p\|_2^{\beta}$ for $\alpha > 0$. Suppose that condition (C1) is satisfied for $(H_1, H_2, S)$. If $S$ contains a curve of the form $\left\{(z_1, g(z_1)) \mid x \in I \right\}$ for any open interval $I$ and any differentiable function $g$, then for any $z_1 \in I$, it holds that: 
\[g'(z_1) \cdot \left(\frac{\beta - 2}{\beta} \cos(\theta^* - 2 \theta) - \cos(\theta^*) \right) \le 0.\]
\end{lemma}

\begin{lemma}
\label{lemma:secondderiv} 
Let there be 2 users located at $u_1, u_2 \in \mathbb{R}_{\ge 0}^D$ such that  $\|u_1\| = \|u_2\| = 1$, and let $\theta^* := \cos^{-1}\left( \langle u_1, u_2\rangle \right) > 0$ be the angle between the user vectors. Let the cost function be $c(\p) = \alpha \|p\|_2^{\beta}$ for $\alpha > 0$. If $z$ is of the form $[r \cos(\theta), r \cos(\theta^* - \theta)]$ for $\theta \in [0, \theta^*]$, then the sign of $\frac{\partial^2  c_{\UMatrix}(z)}{\partial z_1 \partial z_2}$ is equal to the sign of:
\[\frac{\beta - 2}{\beta} \cos(\theta^* - 2 \theta) - \cos(\theta^*).\]
\end{lemma}

\begin{lemma}
\label{lemma:standardbasismax}
For any $\beta \ge 2$, the expression
\[\max_{z_1, z_2 \ge 0} \left(\left(\min\left(\left(\frac{2}{\beta} \right)^{-2/\beta} z_1^2, 1\right) + \min\left(\left(\frac{2}{\beta} \right)^{-2/\beta} z_2^2, 1\right)\right) - (z_1^2 + z_2^2)^{\beta / 2}\right)\]
is maximized for any $(z_1, z_2)$ such that $z_1^2 + z_2^2 = \left(\frac{2}{\beta}\right)^{2/\beta}$. 
\end{lemma}

\begin{lemma}
\label{lemma:supinf}
For any set $\mathcal{R} \subseteq \bR_{> 0}^N$, it holds that:
\[\sup_{y' \in \mathcal{R}} \inf_{y \in \mathcal{R}}  \sum_{i=1}^N  \frac{y'_i}{y_i} = N. \] 
\end{lemma}
\begin{proof}
By taking $y' = y$, we see that:
\[\sup_{y' \in \mathcal{R}} \inf_{y \in \mathcal{R}}  \sum_{i=1}^N  \frac{y'_i}{y_i} \le N. \]
To show equality, notice by AM-GM that:
\[\sum_{i=1}^N  \frac{y'_i}{y_i} \ge N \left(\prod_{i=1}^n \frac{y'_i}{y_i}\right)^{1/N} = N \left(\frac{\prod_{i=1}^n y'_i}{\prod_{i=1}^N y_i}\right)^{1/N}. \]
We can take $y' = \argmax_{y'' \in \mathcal{R}} \prod_{i=1}^n y''_i$, and obtain a lower bound of $N$ as desired. (If the $\argmax$ does not exist, then note that if we take $y'$ where $\prod_{i=1}^n y'_i$ is sufficiently close to the optimum $\sup_{y'' \in \mathcal{R}} \prod_{i=1}^n y''_i$, we have that $\inf_{y \in \mathcal{R}}  \left(\frac{\prod_{i=1}^n y'_i}{\prod_{i=1}^N y_i}\right)^{1/N}$ is sufficiently close to $1$ as desired.)

We first provide a tight geometric characterization of when a marketplace is in the single-genre regime versus in the multi-genre regime. More formally, let $\UMatrix = [\u_1; \cdots; \u_N]$ be the $N \times D$ matrix of user vectors, and let $\Set$ denote the image of the unit ball under $\UMatrix$: 
\begin{equation}
  \Set := \left\{\UMatrix\p \mid \|\p\| \le 1, \p \in \bR_{\ge 0}^D  \right\}  
\end{equation}
Each element of $\Set$ is an $N$-dimensional vector, which represents the inferred user values for some unit-norm producer $\p$. Additionally, let $\Set^{\beta}$ be the image of $\Set$ under coordinate-wise powers, i.e.~if $(z_1, \ldots, z_N) \in \Set$ then $(z_1^{\beta}, \ldots, z_N^{\beta}) \in \Set^{\beta}$.
We show that genres emerge when $\Set^{\beta}$ is sufficiently different from its convex hull $\bar{\Set}^{\beta}$:

\begin{proposition}
\label{prop:atom}
For any set of users and any $\beta \ge 1$, every symmetric mixed equilibrium is atomless.
\end{proposition}

\begin{restatable}{proposition}{existence}
\label{prop:existence}
For any set of users and any $\beta \ge 1$, a symmetric mixed equilibrium exists. 
\end{restatable}

\begin{restatable}{proposition}{finitegenre}
\label{prop:finitegenre}
Consider the setup in Theorem \ref{thm:phasetransitionformal}. If $\beta > \beta^* = \frac{2}{1 - \cos(\theta^*)}$, if $|\Genre(\mu)| < \infty$, and if the conditional distribution of $\|p\|$ along each genre is continuous differentiable, then $\mu$ is not an equilibrium.
\end{restatable}

We next vary the number of producers $P$ while fixing $\beta = 2$ (see Figure \ref{fig:equilibriaP}). \begin{restatable}{proposition}{finiteP}
\label{prop:finiteP}
Suppose that there are 2 users located at the standard basis vectors $e_1, e_2 \in \mathbb{R}^2$, with cost function $c(\p) = \|p\|_2^{\beta}$. For $\beta = 2$, there is a multi-genre equilibrium $\mu$ with support equal to
\begin{equation}
\big\{\big(x, (1 -  x^{\frac{2}{P-1}})^{\frac{P-1}{2}}\big) \mid x \in [0,1] \big\},
\end{equation}
and where the distribution of $x$ has cdf equal to $\min(1, x^{2/(P-1)})$. 
\end{restatable}

\begin{restatable}{proposition}{Ptwo}
\label{prop:P2}
Suppose that there are 2 users located at the standard basis vectors $e_1, e_2 \in \mathbb{R}^2$, and the cost function is $c(\p) = \|p\|_2^{\beta}$. For $P = 2$ and $\beta \ge \beta^* = 2$, there is an equilibrium $\mu$ supported on the quarter-circle of radius $(2 \beta^{-1})^{1/\beta}$, where the angle $\theta \in [0, \pi/2]$ has density $f(\theta) = 2 \cos(\theta) \sin(\theta)$. 
\end{restatable}

\begin{restatable}{proposition}{pure}
\label{prop:pure}
For any set of users and any $\beta \ge 1$, a pure strategy equilibrium does not exist.
\end{restatable}

\begin{restatable}{proposition}{supportrestriction}
\label{prop:supportrestriction}
Suppose that there are $N$ users split equally between two linearly independently vectors $u_1, u_2 \in \mathbb{R}_{\ge 0}^2$, and let $\theta^* := \cos^{-1}\left( \frac{\langle u_1, u_2\rangle}{\|u_1\|_2 \|u_2\|} \right)$ be the angle between the user vectors. Let the cost function be $c(\p) = \|p\|_2^{\beta}$, and let $P \ge 2$. Let $\mu$ be a symmetric Nash equilibrium such that the distributions $\langle u_1, \p\rangle$ and $\langle u_2, \p\rangle$ over $\mathbb{R}_{\ge 0}$ are absolutely continuous. As long as $\beta \neq 2$ or $\theta^* \neq \pi /2$, the support of $\mu$ does not contain an $\ell_2$-ball of radius $\epsilon$ for any $\epsilon > 0$.\footnote{The case of $\beta = 2$ and $\theta^* = \pi/2$ is degenerate and permits a range of possible equilibria.} 
\end{restatable}

\begin{restatable}{proposition}{uniqueness}
\label{prop:uniqueness}
Consider the setup in Theorem \ref{thm:phasetransitionformal}. If $\beta < \beta^* = \frac{2}{1 - \cos(\theta^*)}$ and $\mu$ is a symmetric mixed equilibrium, then $\mu$ satisfies $|\Genre(\mu)| = 1$. 
\end{restatable}

\begin{restatable}{proposition}{utility}
\label{thm:utility}
Suppose that 
\begin{equation}
\label{eq:positiveprofit}
\max_{\|\p\| \le 1} \min_{1 \le i \le N} \Big\langle \p, \frac{u_i}{||u_i||}\Big\rangle < N^{-P/\beta}.    
\end{equation}
Then for any symmetric equilibrium $\mu$, the profit $\ProfitEq(\mu)$ is strictly positive. 
\end{restatable}

\begin{restatable}{proposition}{zeroutilitysinglegenre}
\label{prop:zeroutilitysinglegenre}
If $\mu$ is a single-genre equilibrium, then the profit $\ProfitEq(\mu)$ is equal to $0$. 
\end{restatable}

To formalize specialization, we need to disentangle two forms of differentiation: (1) differentiation along direction (genre), and (2) differentiation along magnitude (quality). We define specialization as differentiation along genres, and not as differentiation along quality. To focus on the former, we define \textit{genres} as the set of \textit{directions} that arise at a symmetric mixed Nash equilibrium $\mu$: 
\begin{equation}
\label{eq:genredef}
 \Genre(\mu) := \Big\{\frac{\p}{\|\p\|} \mid \p \in \text{supp}(\mu) \Big\},  
\end{equation}
where we normalize by $\|p\|$ to separate out the quality (norm) from the genre (direction). The set of genres $ \Genre(\mu)$ captures the set of content that may arise on the platform in some realization of randomness of the producers' strategies. When an equilibrium has a single genre, all producers cater to an average user, and only a single type of content appears  on the platform. On the other hand, when an equilibrium has multiple genres, many types of digital content are likely to appear on the platform. 



We thus say that \textit{specialization} occurs at an equilibrium $\mu$ if and only if $\mu$ has more than one \textit{genre} (i.e., if and only if $|\Genre(\mu)| > 1$). When specialization does occur at $\mu$, the form of specialization is further captured by the number of genres $|\Genre(\mu)|$ and other properties of the set of genres $\Genre(\mu)$. Note that we define specialization in terms of the \textit{support} of a symmetric mixed equilibrium distribution. In this definition, we implicitly interpret the randomness in the producer strategies as differentiation between producers; this formalization of specialization obviates the need to reason about asymmetric equilibria, thus making the model much more tractable to analyze.

To prove our results in this section, our first step is establish a useful characterization of equilibria that enables us to separately account for the geometry of the users and the number of producers. This takes the form of necessary and sufficient conditions that decouple in terms of two quantities: a set of \textit{marginal distributions} $H_i$,
and the \textit{support} $S \subseteq \mathbb{R}_{\ge 0}^N$. 
\begin{restatable}{lemma}{necessarysuff}
\label{claim:necessarysuff}
Let $\UMatrix = [u_1; u_2; \ldots; u_N]$ be the $N \times D$ matrix of users vectors. Given a set $S \subseteq \mathbb{R}_{\ge 0}^N$ and distributions $H_1, \ldots, H_N$ over $\mathbb{R}_{\ge 0}$, suppose that the following conditions hold:   
\begin{description}
    \item{(C1)} Every $z^* \in S$ is a maximizer of the equation:
    \begin{equation}
\label{eq:reparam}
 \max_{z \in \mathbb{R}_{\ge 0}^D} \sum_{i=1}^N H_i(z_i) - c_{\UMatrix}(z),
\end{equation}
where $c_{\UMatrix}(z) := \min \left\{c(\p) \mid \p \in \mathbb{R}_{\ge 0}^D, \UMatrix p=z  \right\}$.
    \item{(C2)} There exists a random variable $Z$ with support $S$, such that the marginal distribution $Z_i$ has cdf equal to $H_i(z)^{1/(P-1)}$.
    \item{(C3)} $Z$ is distributed as $\UMatrix Y$ with $Y \sim \mu$, for some distribution $\mu$ over $\mathbb{R}_{\ge 0}^D$.  
\end{description} 
Then, the distribution $\mu$ from (C3) is a symmetric mixed Nash equilibrium. Moreover, every symmetric mixed Nash equilibrium $\mu$ is associated with some $(H_1, \ldots, H_N, S)$ that satisfy (C1)-(C3). 
\end{restatable}

\section{When does specialization occur?}\label{sec:specialization}

In order to investigate whether specialization occurs in a given marketplace, we investigate when the set of genres $\Genre(\mu)$ of an equilibrium $\mu$ contains more than one direction. We distinguish between two regimes of marketplaces based on whether or not a single-genre equilibrium exists: 
\begin{enumerate}
    \item A marketplace is in the \textit{single-genre regime} if there exists an equilibrium $\mu$ such that $|\Genre(\mu)| = 1$. All producers thus create content of the same genre.
    \item A marketplace is in the \textit{multi-genre regime} if all equilibria $\mu$ satisfy $|\Genre(\mu)| > 1$. Producers thus necessarily differentiate in the genre of content that they produce. 
\end{enumerate}
To understand these regimes, we ask: \textit{what conditions on the user vectors $u_1, \ldots, u_N$ and the cost function parameters $\|\cdot \|$ and $\beta$ determine which regime the marketplace is in?}

\begin{restatable}{theorem}{phasetransitionformal}
\label{thm:phasetransitionformal}
Suppose that there are $N$ users split equally between two linearly independently vectors $u_1, u_2 \in \mathbb{R}_{\ge 0}^D$, and let $\theta^* := \cos^{-1}\left( \frac{\langle u_1, u_2\rangle}{\|u_1\|_2 \|u_2\|} \right)$ be the angle between the user vectors. Let the cost function be $c(\p) = \|p\|_2^{\beta}$. Let $\mu$ be a a distribution on $\mathbb{R}^d$ such that the distributions $\langle u_1, \p\rangle$ and $\langle u_2, \p\rangle$ over $\mathbb{R}_{\ge 0}$ over $\mathbb{R}_{\ge 0}$ for $p \sim \mu$ are absolutely continuous and twice continuously differentiable within their supports. There are two regimes based on $\beta$ and $\theta^*$: 
\begin{enumerate}
    \item If $\beta < \beta^* = \frac{2}{1 - \cos(\theta^*)}$ and if $\mu$ is a symmetric mixed equilibrium, then $\mu$ satisfies $|\Genre(\mu)| = 1$. 
    \item If $\beta > \beta^* = \frac{2}{1 - \cos(\theta^*)}$, if $|\Genre(\mu)| < \infty$, and if the conditional distribution of $\|p\|$ along each genre is continuously differentiable, then $\mu$ is not an equilibrium. 
\end{enumerate}
\end{restatable}

\begin{restatable}{theorem}{singlegenre}
\label{thm:singlegenre} 
Let $\UMatrix := [\u_1; \cdots; \u_N]$, let $\Set$ be $\left\{\UMatrix\p \mid \|\p\| \le 1, \p \in \bR_{\ge 0}^D  \right\}$, and let $\Set^{\beta}$ be the image of $\Set$ under coordinate-wise powers. Then, there is a symmetric equilibrium $\mu$ with $|\Genre(\mu)| = 1$ if and only if 
\begin{equation}
\label{eq:maxcondition}
  \max_{y \in \Set^{\beta}} \prod_{i=1}^{N} y_i  = \max_{y \in \bar{\Set}^{\beta}} \prod_{i=1}^{N} y_i.
\end{equation}
Otherwise, all symmetric equilibria have multiple genres. Moreover, if \eqref{eq:maxcondition} holds for some $\beta$, it also holds for every $\beta' \leq \beta$. 
\end{restatable}
